mapper.select:
SELECT hra.risk_warning_id, hra.document_name, hra.risk_attachment_id, hra.description, hra.attachment_category, hra.upload_date, ( SELECT wm_concat(fa.attachment_id) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name IN ( 'plm_risk_warning' ) AND hra.risk_attachment_id = fam.table_pk_value ) attachment_id, ( SELECT wm_concat(fa.file_name) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name IN ( 'plm_risk_warning' ) AND hra.risk_attachment_id = fam.table_pk_value ) file_name, ( SELECT su.DESCRIPTION FROM sys_user su WHERE hra.UPLOAD_PERSON = su.user_id ) upload_person_n, hra. STATUS FROM plm_risk_attachment hra
hra.attachment_category in ('RISK_ATT')
and hra.risk_warning_id = #{riskWarningId}

SELECT hra.risk_warning_id as check_id, hra.risk_warning_id, hra.document_name, hra.risk_attachment_id, hra.description, hra.attachment_category, (select max(fa.creation_date) from fnd_atm_attachment fa, fnd_atm_attachment_multi fam where fa.attachment_id = fam.attachment_id and fam.table_name in ('prj_check') and to_char(hra.risk_attachment_id) = fam.table_pk_value) upload_date, ( SELECT wm_concat(fa.attachment_id) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name IN ( 'prj_check' ) AND hra.risk_attachment_id = fam.table_pk_value ) attachment_id, ( SELECT wm_concat(fa.file_name) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name IN ( 'prj_check' ) AND hra.risk_attachment_id = fam.table_pk_value ) file_name, (SELECT su.DESCRIPTION FROM sys_user su WHERE su.user_id = (select max(fa.created_by) from fnd_atm_attachment fa, fnd_atm_attachment_multi fam where fa.attachment_id = fam.attachment_id and fam.table_name in ('prj_check') and to_char(hra.risk_attachment_id) = fam.table_pk_value)) upload_person_n, hra. STATUS FROM plm_risk_attachment hra
hra.attachment_category in ('PRJ_CHECK_ATT')
and hra.risk_warning_id = #{checkId}
